/**
 * Parser de arquivos .env.
 */
const KEY = /^[A-Za-z_][A-Za-z0-9_]*$/;
const ESCAPES = { n: '\n', t: '\t', '"': '"', '\\': '\\' };

/**
 * parseEnv(text) → objeto { CHAVE: 'valor' } (todos os valores são strings).
 *
 * - Linhas separadas por \n ou \r\n; linhas em branco e comentários (# como
 *   primeiro caractere não branco) são ignorados.
 * - Prefixo opcional "export ".
 * - A chave é o trecho antes do primeiro '=' (aparado) e deve casar com KEY.
 * - Valor entre aspas duplas: escapes \n \t \" \\ são interpretados; '#' é texto.
 * - Valor entre aspas simples: literal.
 * - Valor sem aspas: aparado; um '#' precedido de espaço inicia comentário.
 * - Chave repetida: a última ocorrência vence.
 * Erros de sintaxe lançam SyntaxError mencionando "line N" (1-based).
 */
export function parseEnv(text) {
  const out = {};
  const lines = text.split(/\r?\n/);
  lines.forEach((raw, i) => {
    const line = raw.trim();
    if (line === '' || line.startsWith('#')) return;
    const body = line.startsWith('export ') ? line.slice(7) : line;
    const eq = body.indexOf('=');
    if (eq === -1) throw new SyntaxError(`line ${i + 1}: missing '='`);
    const key = body.slice(0, eq).trim();
    if (!KEY.test(key)) throw new SyntaxError(`line ${i + 1}: invalid key '${key}'`);
    out[key] = parseValue(body.slice(eq + 1), i + 1);
  });
  return out;
}

function checkTrailing(rest, lineNo) {
  const t = rest.trim();
  if (t !== '' && !t.startsWith('#')) {
    throw new SyntaxError(`line ${lineNo}: unexpected text after closing quote`);
  }
}

function parseValue(rawRest, lineNo) {
  const v = rawRest.trimStart();
  if (v.startsWith('"')) {
    let s = '';
    for (let j = 1; j < v.length; j++) {
      const c = v[j];
      if (c === '\\') {
        if (j + 1 >= v.length) break;
        const n = v[++j];
        s += Object.hasOwn(ESCAPES, n) ? ESCAPES[n] : '\\' + n;
      } else if (c === '"') {
        checkTrailing(v.slice(j + 1), lineNo);
        return s;
      } else {
        s += c;
      }
    }
    throw new SyntaxError(`line ${lineNo}: unterminated string`);
  }
  if (v.startsWith("'")) {
    const end = v.indexOf("'", 1);
    if (end === -1) throw new SyntaxError(`line ${lineNo}: unterminated string`);
    checkTrailing(v.slice(end + 1), lineNo);
    return v.slice(1, end);
  }
  const m = /(^|\s)#/.exec(v);
  return (m ? v.slice(0, m.index) : v).trimEnd();
}

